file.content:
            results.append(
                {
                    "op": "sm",
                    "before": before_digest,
                    "after": after_digest,
                    "changed": len(changed_sections),
                    "sections": changed_sections,
                    "ok": True,
                }
            )

        else:  # get
            _, cid = op
            connection = connections.get(cid)
            if connection is None:
                fail(EXIT_CONNECTION, "CONNECTION")
